"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2887],{72887:d=>{d.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"03-otkladyvat","title":"Урок 03. Сначала себе: Как откладывать, когда кажется, что нечего","sourceFingerprint":"d6214d4b6f0ec5441eeebf96c56bf803b94579f366632f1e65eda68c368eea90","blocks":[{"id":"b001","markdown":"## Сначала себе"},{"id":"b002","markdown":"Как откладывать, когда кажется, что нечего"},{"id":"b003","markdown":"После аудита у тебя есть цифры: сколько тратишь и где утекает. Теперь их нужно превратить в деньги, которые копятся. На этом шаге большинство делает одну и ту же ошибку."},{"id":"b004","markdown":"### Почему \xabотложу, что останется\xbb не работает"},{"id":"b005","markdown":"Схема знакомая: пришла зарплата, и ты живёшь месяц. В конце смотришь, что осталось, и это откладываешь. Остаётся почти всегда ноль. Сила воли тут ни при чём, так устроены траты. Деньги на карте воспринимаются как доступные. А доступные деньги всегда находят, куда уйти: день рождения, распродажа, сломавшийся чайник или просто тяжёлая неделя."},{"id":"b006","markdown":"Откладывая в конце месяца, ты копишь то, что не успел потратить. Откладывая в начале, тратишь то, что не отложил. Похоже на игру слов, но на практике это разница между нулём и накоплениями."},{"id":"b007","markdown":"### Сначала себе"},{"id":"b008","markdown":"Работает обратная схема. Деньги пришли, и в тот же день заранее выбранная доля уходит на отдельный счёт. На остальное живёшь. Ты платишь себе первым, так же как платишь за квартиру или связь, обязательным платежом. Через пару месяцев привыкаешь жить на то, что осталось, как будто зарплата изначально была чуть меньше."},{"id":"b009","markdown":"КОГДА ОТКЛАДЫВАТЬ \xabОТЛОЖУ, ЧТО ОСТАНЕТСЯ\xbb ЗАРПЛАТА ТРАТЫ МЕСЯЦА ОСТАЛОСЬ: 0 ₽ СНАЧАЛА СЕБЕ ЗАРПЛАТА СЕБЕ: 8% В ТОТ ЖЕ ДЕНЬ ЖИВЁШЬ НА ОСТАЛЬНОЕ КАК НАЛОГ, КОТОРЫЙ ПЛАТИШЬ СЕБЕ"},{"id":"b010","markdown":"### Процент или сумма"},{"id":"b011","markdown":"Подумай, как ты платишь НДФЛ. Работодатель удерживает 13% с каждой зарплаты ещё до того, как деньги приходят к тебе, и за годы ты к этому так привык, что даже не считаешь их своими. Если бы налог нужно было отдавать самому раз в месяц фиксированной суммой, это было бы больно каждый раз."},{"id":"b012","markdown":"Накопления стоит устроить так же: как налог, который ты платишь самому себе, процентом и до того, как увидел деньги."},{"id":"b013","markdown":"У процента есть ещё одно преимущество перед фиксированной суммой. Помнишь из урока 1 про шкафы, которые заполняются вещами, сколько бы места ни было? Если откладывать фиксированные 10 000 ₽, то после повышения зарплаты вся прибавка уйдёт в расходы. Процент растёт вместе с доходом сам, без отдельного решения."},{"id":"b014","markdown":"А если месяц выдался слабым, процент сам станет меньше, и откладывание не превратится в непосильную обязанность, которую хочется бросить."},{"id":"b015","markdown":"### Какой процент выбрать"},{"id":"b016","markdown":"Вернись к аудиту и посмотри, сколько в среднем в месяц уходило в утечки. Раздели это на средний месячный доход, это и будет стартовая доля. Ты и так тратил эти деньги впустую. Например, доход на руки 85 000 ₽, утечки за 3 месяца 21 000 ₽, то есть 7 000 ₽ в месяц. 7 000 / 85 000 ≈ 8%, с этого и начинаешь."},{"id":"b017","markdown":"Если утечек почти нет, начни с 3–5%. Даже 1% лучше нуля: на старте привычка важнее суммы. Ориентир на будущее 10–20% дохода, но не с первого месяца."},{"id":"b018","markdown":"### Как поднимать долю без боли"},{"id":"b019","markdown":"В 2004 году экономисты Ричард Талер и Шломо Бенарци опубликовали результаты эксперимента Save More Tomorrow. Сотрудникам компании предложили не откладывать больше прямо сейчас, а заранее согласиться, что доля накоплений будет расти с каждым следующим повышением зарплаты."},{"id":"b020","markdown":"За 40 месяцев средняя доля накоплений у участников выросла с 3,5% до 13,6%. Урезать текущую жизнь им не пришлось, они отдавали часть денег, которых ещё не видели. Сделай так же: с каждым повышением или премией добавляй к доле накоплений 1–2 процентных пункта, а остаток повышения трать спокойно. Через пару лет окажешься где-то на 15% и толком этого не заметишь."},{"id":"b021","markdown":"Какую долю откладывать и как её поднять без боли?"},{"id":"b022","markdown":"Доход на руки в месяц 85\xa0000 ₽ Утечки за 3 месяца (из аудита) 21\xa0000 ₽ 8%"},{"id":"b023","markdown":"стартовая доля: 7\xa0000 ₽ утечек в месяц \xf7 85\xa0000 ₽"},{"id":"b024","markdown":"Сколько повышений впереди 0 С каждым"},{"id":"b025","markdown":"+1 п.п. +2 п.п. Откладываешь 6\xa0800 ₽ в месяц. Это деньги, которые раньше утекали впустую."},{"id":"b026","markdown":"### Автоматизация"},{"id":"b027","markdown":"Сила воли заканчивается, автоплатёж нет."},{"id":"b028","markdown":"Большинство людей годами не меняют то, что включено по умолчанию: тариф связи, платные услуги в банке, настройки телефона. С деньгами работает то же самое. В 2001 году экономисты Бриджит Мадриан и Деннис Ши изучили американскую компанию, которая стала автоматически записывать новых сотрудников в пенсионную программу с правом отказаться. Доля участников среди новичков выросла с 37% до 86%, хотя по сути не изменилось ничего, кроме галочки по умолчанию."},{"id":"b029","markdown":"Сделай так, чтобы по умолчанию у тебя деньги откладывались, а тратить отложенное требовало усилий. Настроить это можно минут за 15."},{"id":"b030","markdown":"- Открой накопительный счёт, лучше в другом банке, не там, куда приходит зарплата. Чем сложнее достать деньги, тем меньше соблазн. Какой счёт выбрать, разберём в уроках 6 и 9."},{"id":"b031","markdown":"- Настрой автоперевод на день зарплаты или на следующий. В приложениях это обычно называется \xabавтоплатёж\xbb или \xabрегулярный перевод\xbb. Переводы через СБП между своими счетами в разных банках бесплатны в пределах 30 млн ₽ в месяц."},{"id":"b032","markdown":"- Убери этот счёт с главного экрана приложения. Не видишь его, меньше хочется тратить."},{"id":"b033","markdown":"Важно: если зарплата приходит 2 частями, настрой перевод на обе даты, иначе копиться будет только половина."},{"id":"b034","markdown":"### Если доход нерегулярный"},{"id":"b035","markdown":"Фрилансерам, самозанятым и тем, у кого большая часть дохода в премиях, подойдёт немного другая схема."},{"id":"b036","markdown":"- Каждое поступление сразу делишь: доля в накопления, доля на налоги, если ты самозанятый или ИП, остальное на жизнь."},{"id":"b037","markdown":"- Считаешь \xabминимальный месяц\xbb, то есть сумму обязательных трат из корзины 1."},{"id":"b038","markdown":"- Живёшь примерно на минимальный месяц, а всё сверху в хорошие месяцы отправляешь в запас. Плохие месяцы закрываешь из него."},{"id":"b039","markdown":"Доход начинает вести себя почти как зарплата, даже если скачет."},{"id":"b040","markdown":"### Разные цели, разные корзины"},{"id":"b041","markdown":"Складывать все накопления в одну кучу неудобно, лучше разделить по целям:"},{"id":"b042","markdown":"- подушка безопасности на случай потери дохода, её не трогают без серьёзной причины (урок 6);"},{"id":"b043","markdown":"- цели на 1–3 года: отпуск, ремонт, первоначальный взнос;"},{"id":"b044","markdown":"- долгосрочный капитал, который потом годами будет работать на тебя. Это тема следующего модуля."},{"id":"b045","markdown":"Многие банки дают завести несколько накопительных счетов или \xabкопилок\xbb с разными названиями, так сразу видно, на что копишь."},{"id":"b046","markdown":"### А если есть кредиты"},{"id":"b047","markdown":"Откладывать всё равно нужно. Вопрос в том, куда пойдут эти деньги, и зависит это от ставок. Кредитка под 50% годовых съедает больше, чем приносит вклад под 13%. Поэтому каждый рубль, отправленный на её погашение, экономит тебе 50%. Но и отдавать в погашение всё до копейки опасно: первая же поломка снова загонит в долг."},{"id":"b048","markdown":"Поэтому сначала небольшой запас на 1 месяц расходов, а потом все отложенные деньги в погашение дорогих долгов. Подробно в уроке 5."},{"id":"b049","markdown":"### Самое главное"},{"id":"b050","markdown":"- Откладывай в день, когда пришли деньги, а не в конце месяца."},{"id":"b051","markdown":"- Откладывай процент. Стартовая доля это твои утечки или 3–5%."},{"id":"b052","markdown":"- С каждым ростом дохода поднимай долю на 1–2 процентных пункта."},{"id":"b053","markdown":"- Отдельный счёт в другом банке и автоперевод в день зарплаты сделают всё за тебя."},{"id":"b054","markdown":"В следующем уроке разберёмся с долгами: какие нормальные, а какие тебя съедают."}],"terms":[{"id":"ndfl","term":"НДФЛ (налог на доходы физических лиц)","definition":"Налог на доходы физических лиц. В учебных расчётах этого курса используются 13% до 2,4 млн ₽ годового дохода и 15% для следующей ступени. С 2025 года основная шкала прогрессивная; для других видов дохода действуют особые правила. Актуальные ставки и право на вычет проверяйте у ФНС."},{"id":"pervonachalnyy-vznos","term":"Первоначальный взнос","definition":"часть стоимости, которую платишь сам при ипотеке. \xabВсего 10%\xbb звучит необременительно, но дальше ипотека на остаток под высокий процент на десятилетия"},{"id":"protsentnyy-punkt","term":"Процентный пункт","definition":"разница между двумя процентами. Ставка выросла с 4% до 5% — это плюс 1 процентный пункт, но плюс 25% к самой ставке. Их путают постоянно, и на этой путанице строятся громкие заголовки"}],"quizzes":[{"id":"03-otkladyvat-q1","q":"Почему откладывать \xabчто останется в конце месяца\xbb обычно не работает?","options":["Потому что доступные деньги почти всегда находят, куда уйти, и в конце месяца остаётся ноль","Потому что банки не разрешают переводить деньги в конце месяца","Потому что в конце месяца выше налоги"],"correct":0},{"id":"03-otkladyvat-q2","q":"Почему лучше откладывать процент от дохода, а не фиксированную сумму?","options":["Фиксированная сумма облагается налогом","Процент всегда меньше фиксированной суммы","Процент подстраивается под нестабильный доход и растёт вместе с повышением зарплаты"],"correct":2},{"id":"03-otkladyvat-q3","q":"Тебе подняли зарплату на 10 000 ₽. Что советует подход \xabSave More Tomorrow\xbb?","options":["Всё повышение потратить, ты его заслужил","Часть повышения направить в накопления, подняв долю на 1–2 процентных пункта, остальное тратить","Всё повышение отправить в накопления"],"correct":1}],"officialSources":[]}')}}]);